index 0000000..f5b4530
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,56 @@
+import { memoryStore } from "../db/store.js";
+import { AppError } from "../errors.js";
+import { t } from "../i18n/messages.js";
+import { consume } from "../domain/batches.js";
+import { getDish } from "../domain/menu.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { isDate } from "../dates.js";
+import { parseCsv } from "./csv.js";
+
+/** Imports sales atomically, skipping tickets imported by earlier files. */
+export function importSales(store, text) {
+  const lines = text.split(/\r?\n/);
+  const header = parseCsv(lines[0] ?? "")[0] ?? [];
+  const columns = ["ticket", "soldAt", "dishId", "qty"];
+  if (header.length !== columns.length || columns.some((c, i) => header[i]?.trim() !== c))
+    throw new AppError("bad_request", { reason: "row 1: expected ticket,soldAt,dishId,qty" });
+  const staged = memoryStore(store.data);
+  const previous = new Set(staged.data.sales.map((sale) => sale.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (let i = 1; i < lines.length; i++) {
+    const line = lines[i];
+    if (!line.trim()) continue;
+    try {
+      if (!/^(?:[^",]*|"(?:[^"]|"")*")(?:,(?:[^",]*|"(?:[^"]|"")*"))*$/.test(line))
+        throw new AppError("bad_request", { reason: "invalid CSV" });
+      const fields = parseCsv(line)[0];
+      if (fields.length !== 4) throw new AppError("bad_request", { reason: "expected four columns" });
+      const [ticket, soldAt, dishText, qtyText] = fields.map((v) => v.trim());
+      if (!ticket) throw new AppError("bad_request", { reason: "ticket is required" });
+      const instant = /^(\d{4}-\d{2}-\d{2})T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/.exec(soldAt);
+      if (!instant || !Number.isFinite(Date.parse(`${instant[1]}T00:00:00Z`)) || !isDate(instant[1]) || !Number.isFinite(Date.parse(soldAt))) throw new AppError("bad_request", { reason: "invalid soldAt" });
+      if (!/^[1-9]\d*$/.test(dishText) || !Number.isSafeInteger(Number(dishText))) throw new AppError("bad_request", { reason: "invalid dishId" });
+      if (!/^[1-9]\d*$/.test(qtyText) || !Number.isSafeInteger(Number(qtyText))) throw new AppError("bad_request", { reason: "invalid qty" });
+      const dish = getDish(staged, Number(dishText));
+      const recipe = getRecipe(staged, dish.recipeId);
+      if (previous.has(ticket)) continue;
+      const qty = Number(qtyText);
+      const ingredients = scaled(recipe, qty);
+      if (ingredients.some((need) => !Number.isFinite(need.qty) || need.qty < 0))
+        throw new AppError("bad_request", { reason: "invalid ingredient quantity" });
+      const at = new Date(soldAt).toISOString();
+      for (const need of ingredients) {
+        if (need.qty > 0) consume(staged, need.itemId, need.qty, { at, ref: `sale:${ticket}` });
+      }
+      staged.data.sales.push({ ticket, soldAt: at, dishId: dish.id, qty, ingredients });
+      tickets.add(ticket);
+      dishes += qty;
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      throw new AppError("bad_request", { reason: `row ${i + 1}: ${t(error.code, "en", error.params)}` });
+    }
+  }
+  store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
